import{_ as e,o,c as a,ag as s}from"./chunks/framework.qXLDknWC.js";const g=JSON.parse('{"title":"Text Editor","description":"","frontmatter":{},"headers":[],"relativePath":"features/editor.md","filePath":"features/editor.md"}'),n={name:"features/editor.md"};function r(i,t,l,d,p,c){return o(),a("div",null,[...t[0]||(t[0]=[s(`<h1 id="text-editor" tabindex="-1">Text Editor <a class="header-anchor" href="#text-editor" aria-label="Permalink to &quot;Text Editor&quot;">​</a></h1><p>Every text field in Character Vault uses a <strong>CodeMirror 6</strong> editor — a fast, keyboard-friendly editor with AI tools built directly into the toolbar.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>AI toolbar operations require an AI provider to be configured. If you haven&#39;t set one up, see <a href="/CharacterVault/docs/configuration/ai-setup">AI Setup</a>.</p></div><h2 id="ai-toolbar" tabindex="-1">AI Toolbar <a class="header-anchor" href="#ai-toolbar" aria-label="Permalink to &quot;AI Toolbar&quot;">​</a></h2><p>A fixed toolbar sits at the top of every editor. When you select text, the AI buttons become active.</p><h3 id="primary-operations" tabindex="-1">Primary Operations <a class="header-anchor" href="#primary-operations" aria-label="Permalink to &quot;Primary Operations&quot;">​</a></h3><p>These are always visible in the toolbar:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Button</th><th style="text-align:left;">Operation</th><th style="text-align:left;">What It Does</th></tr></thead><tbody><tr><td style="text-align:left;">✨ <strong>Enhance</strong></td><td style="text-align:left;">Expand</td><td style="text-align:left;">Elaborate on the selected text with more detail</td></tr><tr><td style="text-align:left;">🔄 <strong>Rephrase</strong></td><td style="text-align:left;">Rewrite</td><td style="text-align:left;">Rewrite the selection while preserving the meaning</td></tr><tr><td style="text-align:left;">💬 <strong>Custom</strong></td><td style="text-align:left;">Instruct</td><td style="text-align:left;">Type your own instruction for the AI to apply</td></tr></tbody></table><p>The <strong>Custom</strong> button opens an inline text input instead of running immediately. Type your instruction, then press <strong>Enter</strong> or click <strong>Send</strong>. Press <strong>Escape</strong> or <strong>Cancel</strong> to close it without running.</p><div class="tip custom-block"><p class="custom-block-title">Multi-line Input</p><p>All AI toolbar inputs support multi-line text. Press <strong>Shift+Enter</strong> to insert line breaks when writing detailed custom instructions.</p></div><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Custom works even without a selection — you can give instructions about the whole section. For example, type &quot;add more detail&quot; to enhance the entire field at once.</p></div><h3 id="polish-operations" tabindex="-1">Polish Operations <a class="header-anchor" href="#polish-operations" aria-label="Permalink to &quot;Polish Operations&quot;">​</a></h3><p>Click <strong>▼ More</strong> to reveal a dropdown with additional operations:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Button</th><th style="text-align:left;">Operation</th><th style="text-align:left;">What It Does</th></tr></thead><tbody><tr><td style="text-align:left;">✂️ <strong>Shorten</strong></td><td style="text-align:left;">Shorten</td><td style="text-align:left;">Condense the selected text</td></tr><tr><td style="text-align:left;">📄 <strong>Lengthen</strong></td><td style="text-align:left;">Lengthen</td><td style="text-align:left;">Extend the selection with additional content</td></tr><tr><td style="text-align:left;">🎨 <strong>Vivid</strong></td><td style="text-align:left;">Vivid</td><td style="text-align:left;">Apply vivid, descriptive language</td></tr><tr><td style="text-align:left;">❤️ <strong>Emotion</strong></td><td style="text-align:left;">Emotion</td><td style="text-align:left;">Enhance emotional expression</td></tr><tr><td style="text-align:left;">🪄 <strong>Fix</strong></td><td style="text-align:left;">Grammar</td><td style="text-align:left;">Fix grammar and improve clarity</td></tr></tbody></table><h3 id="ai-operation-results" tabindex="-1">AI Operation Results <a class="header-anchor" href="#ai-operation-results" aria-label="Permalink to &quot;AI Operation Results&quot;">​</a></h3><p>After an AI operation finishes, a result panel appears below the toolbar showing the AI&#39;s output.</p><p><strong>Selection Info</strong></p><p>When text is selected, the right side of the toolbar shows the character count. If your selection is too long for the AI&#39;s context window, a warning appears and the buttons are disabled.</p><p><strong>Accept or Reject</strong></p><ul><li><strong>✓ Accept</strong> — Replaces your selection with the AI result.</li><li><strong>✕ Reject</strong> — Discards the AI result and keeps your original text.</li></ul><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Accepted text gets a brief green highlight so you can spot what changed. It fades after a moment.</p></div><p><strong>Stop</strong></p><p>While an AI operation is running, a <strong>⏹ Stop</strong> button replaces the toolbar buttons. Click it to cancel the request.</p><p><strong>Reasoning</strong></p><p>If the AI model produces reasoning (thinking) output, a collapsible <strong>&quot;✨ Thinking process&quot;</strong> section appears in the result panel. It auto-expands during streaming and can be toggled after the operation completes.</p><p><strong>Performance Stats</strong></p><p>When an AI operation completes, performance metrics appear in the top-right corner of the result panel:</p><ul><li><strong>TTFT</strong> — Time to First Token. How long the AI took to start responding (in milliseconds). Lower is better.</li><li><strong>T/S</strong> — Tokens per Second. How fast the AI generated tokens after the first one. Higher is better.</li></ul><h2 id="search-replace" tabindex="-1">Search &amp; Replace <a class="header-anchor" href="#search-replace" aria-label="Permalink to &quot;Search &amp; Replace&quot;">​</a></h2><p>Click the 🔍 button in the toolbar, or press <code>Ctrl+F</code> / <code>Cmd+F</code>.</p><ul><li><strong>Find</strong> — Type in the search field. Matches are highlighted in the editor.</li><li><strong>Navigate</strong> — Use the <strong>^</strong> and <strong>v</strong> buttons (or <code>Enter</code> / <code>Shift+Enter</code>) to jump between matches.</li><li><strong>Replace</strong> — Type a replacement string and use <strong>Replace</strong> (current match) or <strong>Replace All</strong>.</li><li><strong>Options</strong> — Toggle <strong>Aa</strong> (case-sensitive), <strong>ab</strong> (whole word), or <strong>.</strong>* (regular expression).</li><li><strong>Match counter</strong> — Shows the current match index and total count (e.g., &quot;3/12&quot;).</li><li><strong>Close</strong> — Press <code>Escape</code> or click <strong>×</strong>.</li></ul><p>If you have text selected when opening search, it automatically fills the search field.</p><h2 id="font-size" tabindex="-1">Font Size <a class="header-anchor" href="#font-size" aria-label="Permalink to &quot;Font Size&quot;">​</a></h2><p>Click the <strong>aA</strong> button in the toolbar to open a font size slider.</p><ul><li>Drag the slider to adjust size (6px – 32px).</li><li>The size updates on release and is remembered across sections.</li><li>The slider popup closes when you click outside it.</li></ul><h2 id="normalize-html-entities" tabindex="-1">Normalize HTML Entities <a class="header-anchor" href="#normalize-html-entities" aria-label="Permalink to &quot;Normalize HTML Entities&quot;">​</a></h2><p>Click the <strong>;&amp;</strong> button in the toolbar to normalize HTML entities into readable characters.</p><ul><li>If text is selected, only the selection is normalized.</li><li>If nothing is selected, the whole editor document is normalized.</li><li>Useful when imported cards contain text like <code>&amp;nbsp;</code>, <code>&amp;amp;</code>, <code>&amp;quot;</code>, or numeric entities.</li></ul><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>This is available in every text editor that uses the shared CodeMirror toolbar, including standard fields, Greetings, Lorebook entry content, Creator Notes, and Extensions.</p></div><h2 id="editor-features" tabindex="-1">Editor Features <a class="header-anchor" href="#editor-features" aria-label="Permalink to &quot;Editor Features&quot;">​</a></h2><ul><li><strong>Spellcheck</strong> — Native browser spellcheck is enabled.</li><li><strong>Undo/Redo</strong> — Standard <code>Ctrl+Z</code> / <code>Ctrl+Shift+Z</code> support.</li><li><strong>Line wrapping</strong> — Long lines wrap automatically.</li><li><strong>Theme sync</strong> — The editor follows the app&#39;s dark/light mode.</li><li><strong>Auto-save</strong> — Changes are saved as you type. No manual save needed.</li></ul><h2 id="section-layout" tabindex="-1">Section Layout <a class="header-anchor" href="#section-layout" aria-label="Permalink to &quot;Section Layout&quot;">​</a></h2><p>Each section tab shows a title, description, and the editor. Some sections have special layouts:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Section</th><th style="text-align:left;">Layout</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Description</strong>, <strong>Personality</strong>, <strong>Scenario</strong>, etc.</td><td style="text-align:left;">Standard single editor</td></tr><tr><td style="text-align:left;"><strong>Creator Notes</strong></td><td style="text-align:left;">Editor with a <strong>Preview CSS</strong> button — opens a sandboxed preview modal, or click again for a side-by-side split view. See <a href="/CharacterVault/docs/features/creator-notes">Creator Notes Preview</a>.</td></tr><tr><td style="text-align:left;"><strong>Greetings</strong></td><td style="text-align:left;">Special multi-greeting editor. See <a href="/CharacterVault/docs/getting-started/creating-characters">Creating &amp; Editing Characters</a>.</td></tr><tr><td style="text-align:left;"><strong>Lorebook</strong></td><td style="text-align:left;">Two-panel editor with search and AI key generation. See <a href="/CharacterVault/docs/features/lorebook-editor">Lorebook Editor</a>.</td></tr><tr><td style="text-align:left;"><strong>Image</strong></td><td style="text-align:left;">Image upload panel (not a text editor)</td></tr><tr><td style="text-align:left;"><strong>Extensions</strong></td><td style="text-align:left;">Raw JSON editor</td></tr></tbody></table><h2 id="customizing-ai-prompts" tabindex="-1">Customizing AI Prompts <a class="header-anchor" href="#customizing-ai-prompts" aria-label="Permalink to &quot;Customizing AI Prompts&quot;">​</a></h2><p>All eight toolbar operation prompts are customizable:</p><ol><li>Open <strong>Settings</strong> in the workspace header.</li><li>Go to the <strong>Prompts</strong> tab.</li><li>Edit the prompt template for any operation.</li></ol><h3 id="required-placeholders" tabindex="-1">Required Placeholders <a class="header-anchor" href="#required-placeholders" aria-label="Permalink to &quot;Required Placeholders&quot;">​</a></h3><p>Prompts must include certain placeholders to work. The system validates these before saving.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Placeholder</th><th style="text-align:left;">Used In</th><th style="text-align:left;">Purpose</th></tr></thead><tbody><tr><td style="text-align:left;"><code>\${text}</code></td><td style="text-align:left;">All operations</td><td style="text-align:left;">The selected or full editor content</td></tr><tr><td style="text-align:left;"><code>\${instruction}</code></td><td style="text-align:left;">Custom only</td><td style="text-align:left;">The custom instruction text</td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">What is a placeholder?</p><p>A <strong>placeholder</strong> is a special token that gets replaced with actual content before the prompt is sent to the AI provider.</p><p><strong>Example:</strong> In the template <code>Enhance the following text: \${text}</code>, the placeholder is replaced with your selection when you click <strong>Enhance</strong>.</p></div><p><strong>Primary prompts</strong> (Enhance, Rephrase) need <code>\${text}</code>. <strong>Polish prompts</strong> (Shorten, Lengthen, Vivid, Emotion, Fix) also need <code>\${text}</code>.</p><p><strong>Custom</strong> is special — it needs both <code>\${instruction}</code> and <code>\${text}</code>. When the editor has content, your template is used. When it&#39;s empty, the system swaps in a generation template instead.</p><details class="details custom-block"><summary>How Custom works with empty editors</summary><p>When the editor is empty, the system swaps the entire prompt template for a generation-oriented one. This lets the Custom button work both as a text modifier <strong>and</strong> a text generator.</p><p><strong>Default Custom template (with editor content):</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Please apply the following instruction to the text below:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Instruction: \${instruction}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Text:</span></span>
<span class="line"><span>&quot;&quot;&quot;</span></span>
<span class="line"><span>\${text}</span></span>
<span class="line"><span>&quot;&quot;&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Provide only the modified text without any additional commentary.</span></span></code></pre></div><p><strong>When the editor is empty</strong>, the template is replaced entirely:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Please generate text based on the following instruction:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Instruction: &lt;your instruction&gt;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Provide only the generated text without any additional commentary.</span></span></code></pre></div><div class="warning custom-block"><p class="custom-block-title">Not yet customizable</p><p>The empty-editor prompt is currently hardcoded and cannot be edited in the Prompts tab. Customization for this prompt is planned for a future release.</p></div></details><blockquote><p>Don&#39;t worry if you forget — you can&#39;t save a prompt without the required placeholders. An error message will remind you to include them.</p></blockquote><h2 id="next-steps" tabindex="-1">Next Steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next Steps&quot;">​</a></h2><ul><li><a href="/CharacterVault/docs/features/lorebook-editor">Lorebook editor</a></li><li><a href="/CharacterVault/docs/features/creator-notes">Creator Notes preview</a></li><li><a href="/CharacterVault/docs/features/ai-assistant">AI Assistant — Orion</a></li><li><a href="/CharacterVault/docs/configuration/ai-setup">Configure AI provider</a></li></ul>`,57)])])}const u=e(n,[["render",r]]);export{g as __pageData,u as default};
